-- Converted from CockroachDB (SHOW CREATE ALL TABLES).
-- Columns and primary keys only. Indexes, unique indexes, CHECK constraints
-- and foreign keys are in 03_constraints.sql, which runs AFTER the data load.
-- Run as appuser, after 00_extensions.sql.
--
-- Conversions applied:
--   STRING -> TEXT, INT8 -> BIGINT, FLOAT8 -> DOUBLE PRECISION, FLOAT4 -> REAL,
--   BOOL -> BOOLEAN, VECTOR(384) -> pgvector VECTOR(384),
--   DEFAULT unique_rowid() -> GENERATED BY DEFAULT AS IDENTITY,
--   now():::TIMESTAMPTZ -> now(), 'x':::STRING -> 'x', 0:::INT8 -> 0,
--   removed ASC from primary keys and WITH (schema_locked = true).

CREATE TABLE public.ask_log (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    session_token TEXT NULL,
    ip_hash TEXT NULL,
    query TEXT NOT NULL,
    mode TEXT NOT NULL,
    professor_slug TEXT NULL,
    result_status TEXT NOT NULL,
    retrieved_count BIGINT NULL,
    answer_text TEXT NULL,
    tokens_used BIGINT NULL,
    response_ms BIGINT NULL,
    flagged BOOLEAN NULL DEFAULT false,
    created_at TIMESTAMPTZ NULL DEFAULT now(),
    CONSTRAINT ask_log_pkey PRIMARY KEY (id)
);

CREATE TABLE public.bookmarks (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    user_sub TEXT NOT NULL,
    item_type TEXT NOT NULL,
    item_key TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT bookmarks_pkey PRIMARY KEY (id)
);

CREATE TABLE public.evidence (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    source TEXT NOT NULL,
    source_ref TEXT NOT NULL,
    professor_slug TEXT NULL,
    course_code TEXT NULL,
    body TEXT NOT NULL,
    body_tsv TSVECTOR NULL,
    body_sha TEXT NOT NULL,
    sentiment TEXT NULL,
    reddit_score BIGINT NULL,
    permalink TEXT NULL,
    rmp_meta JSONB NULL,
    flagged BOOLEAN NULL DEFAULT false,
    subreddit TEXT NULL,
    created_utc TIMESTAMPTZ NULL,
    CONSTRAINT evidence_pkey PRIMARY KEY (id)
);

CREATE TABLE public.evidence_embeddings (
    evidence_id UUID NOT NULL,
    embedding VECTOR(384) NOT NULL,
    model_version TEXT NOT NULL,
    body_sha TEXT NULL,
    embedded_at TIMESTAMPTZ NULL DEFAULT now(),
    CONSTRAINT evidence_embeddings_pkey PRIMARY KEY (evidence_id)
);

CREATE TABLE public.professor_photos (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name TEXT NOT NULL,
    image_url TEXT NULL,
    source_page TEXT NULL,
    focus_x DOUBLE PRECISION NULL,
    focus_y DOUBLE PRECISION NULL,
    CONSTRAINT professor_photos_pkey PRIMARY KEY (id)
);

CREATE TABLE public.professor_tags (
    name_key TEXT NOT NULL,
    tag TEXT NOT NULL,
    review_count BIGINT NOT NULL DEFAULT 0,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT professor_tags_pkey PRIMARY KEY (name_key, tag)
);

CREATE TABLE public.professor_teaching (
    professor_slug TEXT NOT NULL,
    name_key TEXT NOT NULL,
    term_desc TEXT NOT NULL,
    term_codes TEXT NOT NULL,
    course_codes TEXT NOT NULL,
    campuses TEXT NULL,
    match_method TEXT NOT NULL,
    scraped_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT professor_teaching_pkey PRIMARY KEY (name_key, term_desc)
);

CREATE TABLE public.reddit_mentions (
    mention_id TEXT NOT NULL,
    source_type TEXT NOT NULL,
    source_id TEXT NOT NULL,
    thread_id TEXT NULL,
    professor_slug TEXT NOT NULL,
    name_key TEXT NOT NULL,
    method TEXT NOT NULL,
    confidence DOUBLE PRECISION NULL,
    verify_verdict TEXT NULL,
    verify_quote TEXT NULL,
    CONSTRAINT reddit_mentions_pkey PRIMARY KEY (mention_id)
);

CREATE TABLE public.reddit_sentiment (
    source_type TEXT NOT NULL,
    source_id TEXT NOT NULL,
    professor_slug TEXT NOT NULL,
    sentiment TEXT NOT NULL,
    score DOUBLE PRECISION NOT NULL,
    on_topic BOOLEAN NULL,
    sarcasm BOOLEAN NULL,
    hyperbole BOOLEAN NULL,
    rationale TEXT NULL,
    CONSTRAINT reddit_sentiment_pkey PRIMARY KEY (source_type, source_id, professor_slug)
);

CREATE TABLE public.reddit_text (
    source_id TEXT NOT NULL,
    source_type TEXT NOT NULL,
    subreddit TEXT NULL,
    body TEXT NOT NULL,
    score BIGINT NULL,
    created_utc TIMESTAMPTZ NULL,
    permalink TEXT NULL,
    body_tsv TSVECTOR NULL,
    flagged BOOLEAN NULL DEFAULT false,
    flag_reason TEXT NULL,
    CONSTRAINT reddit_text_pkey PRIMARY KEY (source_id)
);

CREATE TABLE public.review_tags (
    source TEXT NOT NULL,
    source_id BIGINT NOT NULL,
    tag TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT review_tags_pkey PRIMARY KEY (source, source_id, tag)
);

CREATE TABLE public.review_tags_processed (
    source TEXT NOT NULL,
    source_id BIGINT NOT NULL,
    taxonomy_version BIGINT NOT NULL DEFAULT 1,
    processed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT review_tags_processed_pkey PRIMARY KEY (source, source_id)
);

CREATE TABLE public.rmp_professors (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name TEXT NOT NULL,
    department TEXT NULL,
    rating REAL NULL,
    num_ratings BIGINT NULL,
    would_take_again_pct TEXT NULL,
    level_of_difficulty REAL NULL,
    professor_url TEXT NULL,
    CONSTRAINT rmp_professors_pkey PRIMARY KEY (id)
);

CREATE TABLE public.rmp_reviews (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    professor_name TEXT NOT NULL,
    department TEXT NULL,
    overall_rating REAL NULL,
    course TEXT NULL,
    quality REAL NULL,
    difficulty REAL NULL,
    date TEXT NULL,
    tags TEXT NULL,
    attendance TEXT NULL,
    grade TEXT NULL,
    textbook TEXT NULL,
    online_class TEXT NULL,
    comment TEXT NULL,
    name_key TEXT NULL,
    course_code TEXT NULL,
    CONSTRAINT rmp_reviews_pkey PRIMARY KEY (id)
);

CREATE TABLE public.stats_cache (
    key TEXT NOT NULL,
    value BIGINT NULL,
    CONSTRAINT stats_cache_pkey PRIMARY KEY (key)
);

CREATE TABLE public.usage_alerts (
    alert_date DATE NOT NULL,
    tier BIGINT NOT NULL,
    sent_at TIMESTAMPTZ NULL DEFAULT now(),
    CONSTRAINT usage_alerts_pkey PRIMARY KEY (alert_date, tier)
);

CREATE TABLE public.banner_terms (
    term_code TEXT NOT NULL,
    term_desc_raw TEXT NULL,
    term_label TEXT NOT NULL,
    season TEXT NOT NULL,
    season_group TEXT NOT NULL,
    year BIGINT NOT NULL,
    track TEXT NULL,
    view_only BOOLEAN NOT NULL,
    scraped_closed BOOLEAN NOT NULL,
    section_count BIGINT NOT NULL,
    attributed_sections BIGINT NOT NULL,
    instructor_count BIGINT NOT NULL,
    instructors_source TEXT NOT NULL,
    first_seen_at TIMESTAMPTZ NULL,
    scraped_at TIMESTAMPTZ NULL DEFAULT now(),
    CONSTRAINT banner_terms_pkey PRIMARY KEY (term_code)
);

CREATE TABLE public.banner_sections (
    term_code TEXT NOT NULL,
    crn TEXT NOT NULL,
    subject TEXT NULL,
    subject_course TEXT NULL,
    course_number TEXT NULL,
    section TEXT NULL,
    course_title TEXT NULL,
    campus TEXT NULL,
    instructional_method TEXT NULL,
    schedule_type TEXT NULL,
    credit_hours_low DOUBLE PRECISION NULL,
    credit_hours_high DOUBLE PRECISION NULL,
    enrollment BIGINT NULL,
    part_of_term TEXT NULL,
    CONSTRAINT banner_sections_pkey PRIMARY KEY (term_code, crn)
);

CREATE TABLE public.banner_section_instructors (
    term_code TEXT NOT NULL,
    crn TEXT NOT NULL,
    instructor_key TEXT NOT NULL,
    instructor_name TEXT NOT NULL,
    is_primary BOOLEAN NULL,
    source TEXT NOT NULL DEFAULT 'banner',
    CONSTRAINT banner_section_instructors_pkey PRIMARY KEY (term_code, crn, instructor_key)
);

CREATE TABLE public.banner_unmatched (
    term_desc TEXT NOT NULL,
    instructor_key TEXT NOT NULL,
    instructor_name TEXT NULL,
    course_codes TEXT NULL,
    reason TEXT NOT NULL,
    candidates TEXT NULL,
    scraped_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT banner_unmatched_pkey PRIMARY KEY (term_desc, instructor_key)
);

CREATE TABLE public.banner_course_instructors (
    subject_course TEXT NOT NULL,
    instructor_key TEXT NOT NULL,
    instructor_name TEXT NULL,
    professor_slug TEXT NULL,
    name_key TEXT NULL,
    match_method TEXT NOT NULL,
    terms_taught BIGINT NOT NULL,
    sections BIGINT NOT NULL,
    first_term_code TEXT NOT NULL,
    last_term_code TEXT NOT NULL,
    last_term_label TEXT NOT NULL,
    recent_terms TEXT NULL,
    avg_enrollment DOUBLE PRECISION NULL,
    was_primary BOOLEAN NULL,
    campuses TEXT NULL,
    methods TEXT NULL,
    CONSTRAINT banner_course_instructors_pkey PRIMARY KEY (subject_course, instructor_key)
);

CREATE TABLE public.banner_course_offerings (
    subject_course TEXT NOT NULL,
    subject TEXT NULL,
    course_title TEXT NULL,
    first_term_code TEXT NOT NULL,
    last_term_code TEXT NOT NULL,
    last_term_label TEXT NOT NULL,
    terms_offered BIGINT NOT NULL,
    pattern TEXT NOT NULL,
    fall_years BIGINT NOT NULL,
    spring_years BIGINT NOT NULL,
    summer_years BIGINT NOT NULL,
    pattern_window_years BIGINT NOT NULL,
    avg_sections_per_term DOUBLE PRECISION NULL,
    avg_section_size DOUBLE PRECISION NULL,
    median_section_size DOUBLE PRECISION NULL,
    credit_hours TEXT NULL,
    instructor_count BIGINT NOT NULL,
    offered_now TEXT NULL,
    summer1_years BIGINT NOT NULL DEFAULT 0,
    summer2_years BIGINT NOT NULL DEFAULT 0,
    first_term_label TEXT NULL,
    offering_years TEXT NULL,
    CONSTRAINT banner_course_offerings_pkey PRIMARY KEY (subject_course)
);

CREATE TABLE public.banner_course_rename_candidates (
    old_code TEXT NOT NULL,
    new_code TEXT NOT NULL,
    title TEXT NULL,
    old_last_term TEXT NULL,
    new_first_term_code TEXT NULL,
    same_subject BOOLEAN NULL,
    shared_instructors TEXT NULL,
    approved BOOLEAN NOT NULL,
    CONSTRAINT banner_course_rename_candidates_pkey PRIMARY KEY (old_code, new_code)
);

CREATE TABLE public.banner_course_renames (
    old_code TEXT NOT NULL,
    new_code TEXT NOT NULL,
    CONSTRAINT banner_course_renames_pkey PRIMARY KEY (old_code)
);

CREATE TABLE public.banner_roster_duplicates (
    term_code TEXT NOT NULL,
    instructor_key TEXT NOT NULL,
    CONSTRAINT banner_roster_duplicates_pkey PRIMARY KEY (term_code, instructor_key)
);

CREATE TABLE public.professors (
    slug TEXT NOT NULL,
    name TEXT NOT NULL,
    name_key TEXT NOT NULL,
    department TEXT NULL,
    college TEXT NULL,
    image_url TEXT NULL,
    focus_x DOUBLE PRECISION NULL,
    focus_y DOUBLE PRECISION NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT professors_pkey PRIMARY KEY (slug)
);

CREATE TABLE public.rmp_links (
    rmp_id BIGINT NOT NULL,
    rmp_name TEXT NOT NULL,
    rmp_department TEXT NULL,
    professor_url TEXT NOT NULL,
    slug TEXT NOT NULL,
    match_method TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT rmp_links_pkey PRIMARY KEY (rmp_id)
);

CREATE TABLE public.catalog_courses (
    code TEXT NOT NULL,
    subject TEXT NULL,
    number TEXT NULL,
    name TEXT NULL,
    department TEXT NULL,
    credit_hours TEXT NULL,
    credit_min DOUBLE PRECISION NULL,
    credit_max DOUBLE PRECISION NULL,
    description TEXT NULL,
    prerequisites TEXT NULL,
    corequisites TEXT NULL,
    search_text TEXT NULL,
    subject_slug TEXT NULL,
    catalog_year TEXT NULL,
    is_placeholder BOOLEAN NOT NULL DEFAULT false,
    scraped_at TIMESTAMPTZ NULL DEFAULT now(),
    CONSTRAINT catalog_courses_pkey PRIMARY KEY (code)
);

CREATE TABLE public.catalog_nupath (
    code TEXT NOT NULL,
    attribute TEXT NOT NULL,
    CONSTRAINT catalog_nupath_pkey PRIMARY KEY (code, attribute)
);

CREATE TABLE public.professors_catalog (
    slug TEXT NOT NULL,
    name TEXT NOT NULL,
    name_key TEXT NOT NULL,
    department TEXT NULL,
    college TEXT NULL,
    avg_rating DOUBLE PRECISION NULL,
    rmp_rating DOUBLE PRECISION NULL,
    num_ratings BIGINT NULL DEFAULT 0,
    total_reviews BIGINT NULL DEFAULT 0,
    would_take_again_pct DOUBLE PRECISION NULL,
    difficulty DOUBLE PRECISION NULL,
    professor_url TEXT NULL,
    image_url TEXT NULL,
    focus_x DOUBLE PRECISION NULL,
    focus_y DOUBLE PRECISION NULL,
    total_comments BIGINT NULL DEFAULT 0,
    CONSTRAINT professors_catalog_new_pkey PRIMARY KEY (slug)
);

CREATE TABLE public.course_catalog (
    code TEXT NOT NULL,
    name TEXT NULL,
    department TEXT NULL,
    subject TEXT NULL,
    search_text TEXT NULL,
    avg_rating DOUBLE PRECISION NULL,
    difficulty DOUBLE PRECISION NULL,
    num_ratings BIGINT NULL DEFAULT 0,
    CONSTRAINT course_catalog_new_pkey PRIMARY KEY (code)
);

CREATE TABLE public.source_summary (
    professor_slug TEXT NOT NULL DEFAULT '',
    course_code TEXT NOT NULL DEFAULT '',
    source TEXT NOT NULL,
    rating DOUBLE PRECISION NULL,
    difficulty DOUBLE PRECISION NULL,
    would_take_again_pct DOUBLE PRECISION NULL,
    num_ratings BIGINT NOT NULL DEFAULT 0,
    num_comments BIGINT NOT NULL DEFAULT 0,
    hours_per_week DOUBLE PRECISION NULL,
    rating_distribution JSONB NULL,
    grade_distribution JSONB NULL,
    CONSTRAINT source_summary_new_pkey PRIMARY KEY (professor_slug, course_code, source)
);
